import{_ as t,o as n,c as o,a0 as a}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"ADR 0035: The control plane runs on Bun","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0035-the-control-plane-runs-on-bun.md","filePath":"adr/0035-the-control-plane-runs-on-bun.md"}'),s={name:"adr/0035-the-control-plane-runs-on-bun.md"};function r(i,e,d,h,c,l){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0035-the-control-plane-runs-on-bun" tabindex="-1">ADR 0035: The control plane runs on Bun <a class="header-anchor" href="#adr-0035-the-control-plane-runs-on-bun" aria-label="Permalink to &quot;ADR 0035: The control plane runs on Bun&quot;">​</a></h1><p>Status: accepted Date: 2026-09-19</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The control plane renders through OpenTUI, whose native core talks to the terminal through FFI: it opens the pseudo-terminal and reads the terminal&#39;s state directly. On the Node runtime that FFI is experimental and gated behind the <code>--experimental-ffi</code> flag, so the bin had to check the version, re-spawn itself with the flag, and hand the process across the boundary before the renderer could load. Node&#39;s SQLite binding added a second problem: the node:sqlite use-after-free in Node 26.5.0 crashed a mutation run, and a crash guard had to contain the orphaned children.</p><p>Bun ships stable, built-in FFI (<code>bun:ffi</code>) and SQLite (<code>bun:sqlite</code>) with no flag and no re-spawn. OpenCode, the production OpenTUI application, runs on Bun for exactly this reason. The version gate and the re-spawn wrapper exist only to satisfy Node&#39;s experimental FFI; on Bun they are dead weight.</p><p>The test suite ran on Vitest. It drives the real terminal through FFI for the PTY tests and the real state file through SQLite for the state tests, so the runner already needed both bindings. Bun&#39;s built-in test runner (<code>bun:test</code>) provides them in the same runtime as the app, so one runtime covers the app, the PTY tests, and the state tests.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The control plane runs on Bun <code>1.3.0</code> or newer, replacing Node.</strong> The bin checks the floor against <code>Bun.version</code> and, on a pass, runs the production entry in the same process. There is no re-spawn and no <code>--experimental-ffi</code> flag: Bun&#39;s FFI is stable and built in.</p><p><strong>The test suite runs on <code>bun:test</code>, replacing Vitest.</strong> The PTY tests open the terminal through <code>bun:ffi</code>; the state tests open the state file through <code>bun:sqlite</code>. One runtime drives the app and every test that touches a native binding.</p><p><strong>Bun owns the package.</strong> Dependencies install through <code>bun install</code> against <code>bun.lock</code>, and the scripts run on Bun, including the VitePress docs build. Node stays for the two things only Node does: the <code>npm publish</code> of the release, and the <code>npx</code> bootstrap of the launcher, which then hands the app to Bun on the <code>PATH</code>.</p><p>ADR 0001&#39;s framework choice - OpenTUI and its first-party React binding, in plain TypeScript with no build step - is preserved. This ADR supersedes the runtime (Node) and the test runner (vitest) that 0001 named.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The version gate is a simple floor check against <code>Bun.version</code>; the re-spawn wrapper and the <code>--experimental-ffi</code> flag are gone.</li><li>FFI and SQLite are stable and flag-free. The node:sqlite 26.5.0 use-after-free that drove the crash guard is no longer the operating mode; the guard stays as a general containment tool for a native crash in the OpenTUI core.</li><li><code>bun:sqlite</code> reports a missing row as <code>null</code>, not <code>undefined</code>, so the state layer&#39;s no-row checks test for null.</li><li>The npm alias (<code>npx mlsf</code>) bootstraps on Node and re-execs the app under Bun, so a machine needs both runtimes for the <code>npx</code> path; a global install runs the app on Bun alone.</li><li>The Strykr mutation-testing setup is removed with the swap: its containment rode on the node:sqlite crash that Bun removes, and Strykr&#39;s instrumentation of a Bun process is unverified. Re-adding mutation testing on Bun is tracked separately, as is a prebuilt binary distribution.</li></ul>',13)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
